# Helper mock function to be used in test cases
def calculate_stock_volatility(prices):
    # Simple volatility: standard deviation of returns (difference between consecutive prices)
    if len(prices) < 2:
        return 0.0
    returns = [(prices[i+1] - prices[i]) / prices[i] for i in range(len(prices)-1)]
    mean = sum(returns) / len(returns)
    variance = sum((r - mean) ** 2 for r in returns) / len(returns)
    return variance ** 0.5

# Inject the mock function into global scope so portfolio_risk_assessment can use it.
globals()['calculate_stock_volatility'] = calculate_stock_volatility

def portfolio_risk_assessment(portfolio):
    '''
    Takes a dict where keys are stock names and values have 'prices' list and 'allocation' float.
    For each stock, call calculate_stock_volatility(prices),
    multiply by allocation, sum all weighted volatilities.
    Returns: float representing total portfolio risk as weighted sum.
    '''
    total_risk = 0.0
    for stock, data in portfolio.items():
        vol = calculate_stock_volatility(data['prices'])
        total_risk += vol * data['allocation']
    return total_risk

