def parse_sensor_reading(sensor_string):
    '''
    Parses a sensor reading string like 'T:25.5|H:60|TS:1234567890'.
    Returns dictionary with keys 'temperature', 'humidity', 'timestamp'.
    If values are missing or cannot be converted, set as None.
    '''
    key_map = {'T': 'temperature', 'H': 'humidity', 'TS': 'timestamp'}
    result = {'temperature': None, 'humidity': None, 'timestamp': None}

    # Split by '|'
    parts = sensor_string.split('|')
    for part in parts:
        if ':' in part:
            k, v = part.split(':', 1)
            if k in key_map:
                out_key = key_map[k]
                # Attempt conversion
                try:
                    if k in ['T', 'H']:
                        result[out_key] = float(v)
                    elif k == 'TS':
                        result[out_key] = int(v)
                except ValueError:
                    result[out_key] = None
    return result

